window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_physics_de"]=window.LC_CHUNKS["university_physics_de"]||{};window.LC_CHUNKS["university_physics_de"][30]={"university_physics_de:M30-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M30-L1 – Klassische Felder und Klein-Gordon-Gleichung<\/h1>\n<p><strong>Kursbereich:<\/strong> M30 – Master: Quantenfeldtheorie und Standardmodell<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M10: spezielle Relativitätstheorie;\nM13: Variationsprinzip; M25: Quantenmechanik · <a\nhref=\"index.html?course=university_physics&amp;module=M29&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Die Bewegungsgleichung eines reellen\nSkalarfelds aus einer Lagrange-Dichte ableiten und die relativistische\nDispersionsrelation auswerten.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein Feld ordnet jedem Raumzeitpunkt eine physikalische Größe zu.\nAnders als die Bahn einer einzelnen Masse beschreibt die Feldtheorie\nkontinuierlich verteilte Freiheitsgrade. Im relativistischen Modell\ntreten Orts- und Zeitänderungen gemeinsam in einer Lorentz-invarianten\nWirkung auf. Als einfachster Einstieg dient ein freies reelles\nSkalarfeld.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Wir verwenden natürliche Einheiten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ℏ<\/mi><mo>=<\/mo><mi>c<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\hbar=c=1<\/annotation><\/semantics><\/math>\nund die Signatur\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>η<\/mi><mrow><mi>μ<\/mi><mi>ν<\/mi><\/mrow><\/msub><mo>=<\/mo><mrow><mi mathvariant=\"normal\">d<\/mi><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">g<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>+<\/mi><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\eta_{\\mu\\nu}=\\mathrm{diag}(+1,-1,-1,-1)<\/annotation><\/semantics><\/math>;\ndies ist eine explizite Konventionswahl, anders als die in M29\nverwendete Signatur. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"script\">ℒ<\/mi><mo>=<\/mo><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><msub><mi>∂<\/mi><mi>μ<\/mi><\/msub><mi>ϕ<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi>∂<\/mi><mi>μ<\/mi><\/msup><mi>ϕ<\/mi><mo>−<\/mo><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><msup><mi>m<\/mi><mn>2<\/mn><\/msup><msup><mi>ϕ<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal L=\\frac12\\partial_\\mu\\phi\\,\\partial^\\mu\\phi-\\frac12m^2\\phi^2<\/annotation><\/semantics><\/math>\nergibt die Euler-Lagrange-Gleichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>∂<\/mi><mi>μ<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>∂<\/mi><mi mathvariant=\"script\">ℒ<\/mi><mi>/<\/mi><mi>∂<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>∂<\/mi><mi>μ<\/mi><\/msub><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>∂<\/mi><mi mathvariant=\"script\">ℒ<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>ϕ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\partial_\\mu(\\partial\\mathcal L/\\partial(\\partial_\\mu\\phi))-\\partial\\mathcal L/\\partial\\phi=0<\/annotation><\/semantics><\/math>.\nEinsetzen liefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo>□<\/mo><mi>+<\/mi><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>ϕ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(\\Box+m^2)\\phi=0<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>□<\/mo><mo>=<\/mo><msubsup><mi>∂<\/mi><mi>t<\/mi><mn>2<\/mn><\/msubsup><mo>−<\/mo><msup><mi>∇<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\Box=\\partial_t^2-\\nabla^2<\/annotation><\/semantics><\/math>.\nFür eine ebene Welle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ϕ<\/mi><mo>∝<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>i<\/mi><mi>ω<\/mi><mi>t<\/mi><mo>+<\/mo><mi>i<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo>⋅<\/mo><mi mathvariant=\"bold-italic\">𝒙<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\phi\\propto e^{-i\\omega t+i\\mathbf k\\cdot\\mathbf x}<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><msup><mi>ω<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"bold-italic\">𝒌<\/mi><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-\\omega^2+|\\mathbf k|^2+m^2=0<\/annotation><\/semantics><\/math>.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>ω<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"bold-italic\">𝒌<\/mi><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mspace width=\"2.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ℏ<\/mi><mo>=<\/mo><mi>c<\/mi><mo>=<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\omega^2=|\\mathbf k|^2+m^2\\qquad(\\hbar=c=1).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">m=2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|\\mathbf k|=3<\/annotation><\/semantics><\/math>\nerhält man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mo>=<\/mo><msqrt><mn>13<\/mn><\/msqrt><mo>≈<\/mo><mn>3<\/mn><mo>,<\/mo><mn>606<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\omega=\\sqrt{13}\\approx3{,}606<\/annotation><\/semantics><\/math>.\nDie beiden Kurven der Grafik zeigen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mo>=<\/mo><msqrt><mrow><msup><mi>k<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mi>m<\/mi><mn>2<\/mn><\/msup><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">\\omega=\\sqrt{k^2+m^2}<\/annotation><\/semantics><\/math>\nfür verschiedene Massen. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">k=0<\/annotation><\/semantics><\/math>\nbleibt die Ruhefrequenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mo>=<\/mo><mi>m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\omega=m<\/annotation><\/semantics><\/math>,\nwährend bei großen Impulsen der lineare Anteil dominiert.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_255_DE.svg\"\nalt=\"Dispersionsrelationen für zwei freie skalare Felder; mit größerer Masse beginnt die Frequenzkurve bei höherer Ruhefrequenz.\" />\n<figcaption aria-hidden=\"true\">Dispersionsrelationen für zwei freie\nskalare Felder; mit größerer Masse beginnt die Frequenzkurve bei höherer\nRuhefrequenz.<\/figcaption>\n<\/figure>\n<p><em>Die Feldmasse verschiebt die untere Frequenzgrenze einer freien\nrelativistischen Mode.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Gleichung erhält man für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">m=0<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ω<\/mi><annotation encoding=\"application/x-tex\">\\omega<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">m=4<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">k=3<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Welche Annahme wird durch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"script\">ℒ<\/mi><annotation encoding=\"application/x-tex\">\\mathcal L<\/annotation><\/semantics><\/math>\nohne Wechselwirkungsterme getroffen?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>k<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\omega=|k|<\/annotation><\/semantics><\/math>\nfür positive Frequenz.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mo>=<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\omega=5<\/annotation><\/semantics><\/math>\nin natürlichen Einheiten.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Das Skalarfeld ist frei; es streut im Modell nicht über\nSelbstwechselwirkungen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die klassische Feldgleichung ist noch keine Quantentheorie. Die\nKurven nutzen ungekoppelte ebene Wellen und sind keine gemessenen\nTeilchenspektren. Natürliche Einheiten und Metriksignatur müssen bei\njeder Formel konsistent bleiben.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Das freie Skalarfeld bildet die Grundlage der kanonischen\nFeldquantisierung in M30-L2. <a\nhref=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://davidtong.org/teaching/quantum-field-theory/\">Tong – Quantum Field Theory<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel 1: klassische Feldtheorie, Klein-Gordon-Gleichung; Fachlicher Bezug zur Lektion: M30-L1 – Klassische Felder und Klein-Gordon-Gleichung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M30-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M30-L2 – Kanonische Quantisierung und Fock-Zustände<\/h1>\n<p><strong>Kursbereich:<\/strong> M30 – Master: Quantenfeldtheorie und Standardmodell<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M30-L1: freie Feldgleichung; M25:\nharmonischer Oszillator · <a\nhref=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Feldmoden als Quantenoszillatoren\nbeschreiben und Energiedifferenzen zwischen Fock-Zuständen\nbestimmen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Warum werden aus kontinuierlichen Feldschwingungen diskrete\nTeilchenanregungen? Bei der kanonischen Quantisierung erhält jede\nunabhängige freie Mode die Struktur eines harmonischen\nQuantenoszillators. Teilchenzahlen sind Besetzungszahlen solcher Moden;\nein Fock-Zustand kann mehrere identische Bosonen in derselben Mode\nenthalten.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Wie in M30-L1 verwenden wir natürliche Einheiten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ℏ<\/mi><mo>=<\/mo><mi>c<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\hbar=c=1<\/annotation><\/semantics><\/math>;\ndaher ist der Energieabstand einer freien Mode\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>ω<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\omega_{\\mathbf k}<\/annotation><\/semantics><\/math>.\nMit explizitem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ℏ<\/mi><annotation encoding=\"application/x-tex\">\\hbar<\/annotation><\/semantics><\/math>\nwäre er\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ℏ<\/mi><msub><mi>ω<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\hbar\\omega_{\\mathbf k}<\/annotation><\/semantics><\/math>.\nIn einem endlichen Volumen werden zunächst diskrete Impulse\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"bold-italic\">𝒌<\/mi><annotation encoding=\"application/x-tex\">\\mathbf k<\/annotation><\/semantics><\/math>\nverwendet. Für jede Mode gelten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>a<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><mo>,<\/mo><msubsup><mi>a<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo>†<\/mo><\/msubsup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">[a_{\\mathbf k},a_{\\mathbf k}^\\dagger]=1<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><mo>=<\/mo><msubsup><mi>a<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo>†<\/mo><\/msubsup><msub><mi>a<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">N_{\\mathbf k}=a_{\\mathbf k}^\\dagger a_{\\mathbf k}<\/annotation><\/semantics><\/math>.\nDie Zustände\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|n\\rangle<\/annotation><\/semantics><\/math>\nhaben Besetzungszahlen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mi>…<\/mi><\/mrow><annotation encoding=\"application/x-tex\">n=0,1,2,\\dots<\/annotation><\/semantics><\/math>;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>a<\/mi><mo>†<\/mo><\/msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><msqrt><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msqrt><mspace width=\"0.167em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">a^\\dagger|n\\rangle=\\sqrt{n+1}\\,|n+1\\rangle<\/annotation><\/semantics><\/math>.\nDie Hamiltonfunktion einer freien Mode wird zum Hamiltonoperator\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><mo>=<\/mo><msub><mi>ω<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>N<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><mo>+<\/mo><mstyle displaystyle=\"false\"><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><\/mstyle><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">H_{\\mathbf k}=\\omega_{\\mathbf k}(N_{\\mathbf k}+\\tfrac12)<\/annotation><\/semantics><\/math>.\nDer Nullpunktsterm ist im einzelnen Oszillator endlich; die Summe über\nunendlich viele Feldmoden bedarf gesonderter Behandlung.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><msub><mi>ω<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>E<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>−<\/mo><msub><mi>E<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><msub><mi>ω<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E_n=\\left(n+\\frac12\\right)\\omega_{\\mathbf k},\\qquad E_{n+1}-E_n=\\omega_{\\mathbf k}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">m=4<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"bold-italic\">𝒌<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|\\mathbf k|=3<\/annotation><\/semantics><\/math>\nist die Modenfrequenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ω<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><mo>=<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\omega_{\\mathbf k}=5<\/annotation><\/semantics><\/math>.\nDie ersten drei Energien lauten dann\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E_0=2{,}5<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>7<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E_1=7{,}5<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>12<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E_2=12{,}5<\/annotation><\/semantics><\/math>.\nDie Grafik illustriert gleiche Niveauabstände\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ω<\/mi><annotation encoding=\"application/x-tex\">\\omega<\/annotation><\/semantics><\/math>;\ndie gezeichneten Pfeile bedeuten Anhebung der Besetzungszahl um eins,\nnicht räumliche Bewegung.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_096_DE.svg\"\nalt=\"Vier gleich weit voneinander entfernte Energieniveaus eines einzelnen quantisierten Feldmodus mit Aufwärtspfeilen.\" />\n<figcaption aria-hidden=\"true\">Vier gleich weit voneinander entfernte\nEnergieniveaus eines einzelnen quantisierten Feldmodus mit\nAufwärtspfeilen.<\/figcaption>\n<\/figure>\n<p><em>Jede zusätzliche Anregung einer freien bosonischen Mode kostet in\nnatürlichen Einheiten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ℏ<\/mi><mo>=<\/mo><mi>c<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\hbar=c=1<\/annotation><\/semantics><\/math>\ndie Energie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>ω<\/mi><mi mathvariant=\"bold-italic\">𝒌<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\omega_{\\mathbf k}<\/annotation><\/semantics><\/math>.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Was bewirkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>a<\/mi><mo>†<\/mo><\/msup><annotation encoding=\"application/x-tex\">a^\\dagger<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|2\\rangle<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist der Abstand zwischen zwei benachbarten Niveaus bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mo>=<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\omega=5<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Was bezeichnet der Fock-Vakuumzustand?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>a<\/mi><mo>†<\/mo><\/msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><msqrt><mn>3<\/mn><\/msqrt><mspace width=\"0.167em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">a^\\dagger|2\\rangle=\\sqrt3\\,|3\\rangle<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Fünf Energieeinheiten.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Den Zustand ohne Teilchenanregungen in den betrachteten freien\nModen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Dieses einfache Fock-Bild gilt direkt für freie Felder. In\nwechselwirkenden Theorien kann die Identifikation der Zustände\nwesentlich komplizierter sein. Eine absolute Vakuumenergiedichte folgt\nnicht aus einer unregulierten Summe von Nullpunktsenergien.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Aus quantisierten Moden entstehen Feldkorrelationen und zeitgeordnete\nPropagatoren. <a href=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://davidtong.org/teaching/quantum-field-theory/\">Tong – Quantum Field Theory<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel 2: kanonische Quantisierung und freie Felder; Fachlicher Bezug zur Lektion: M30-L2 – Kanonische Quantisierung und Fock-Zustände · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M30-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M30-L3 – Propagatoren und Mikrokausalität<\/h1>\n<p><strong>Kursbereich:<\/strong> M30 – Master: Quantenfeldtheorie und Standardmodell<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M30-L2: Feldoperatoren; M10:\nLichtkegel · <a href=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige\nLektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Zeitordnung und raumartige Trennung\nunterscheiden und den kausalen Inhalt eines Feldkommutators\ninterpretieren.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Eine Quantenfeldtheorie muss sowohl Feldkorrelationen als auch die\nrelativistische Kausalstruktur berücksichtigen. Der Propagator\nbeschreibt in der Störungstheorie die Ausbreitung von Korrelationen. Er\nist nicht mit einer Wahrscheinlichkeit für ein klassisches Signal von A\nnach B gleichzusetzen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für ein freies skalares Feld sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D<\/mi><mi>F<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>T<\/mi><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">D_F(x-y)=\\langle0|T\\phi(x)\\phi(y)|0\\rangle<\/annotation><\/semantics><\/math>.\nDas Symbol\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>\nordnet Operatoren nach Zeit; in Impulsdarstellung ist der\nFeynman-Ausdruck proportional zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>p<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><mi>i<\/mi><mi>ε<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">i/(p^2-m^2+i\\varepsilon)<\/annotation><\/semantics><\/math>.\nDie Zeitordnung allein ist jedoch keine Kausalitätsaussage. Lokalität\nverlangt, dass Feldoperatoren an raumartig getrennten Orten miteinander\nkommutieren, wenn sie Bosonen darstellen. Mit unserer Signatur bedeutet\nraumartig\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>s<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi mathvariant=\"bold-italic\">𝒙<\/mi><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><mo>&lt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s^2=(\\Delta t)^2-|\\Delta\\mathbf x|^2&lt;0<\/annotation><\/semantics><\/math>.\nTrotz eines eventuell nichtverschwindenden zeitgeordneten Korrelators\nkann dadurch keine schneller-als-Licht-Kommunikation konstruiert\nwerden.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>0<\/mn><mspace width=\"1.0em\"><\/mspace><mtext mathvariant=\"normal\">für<\/mtext><mspace width=\"1.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><mi>y<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>&lt;<\/mo><mn>0<\/mn><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">[\\phi(x),\\phi(y)]=0\\quad\\text{für}\\quad (x-y)^2&lt;0.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Zwischen zwei Ereignissen mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t=2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>x<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|\\Delta x|=3<\/annotation><\/semantics><\/math>\nin Einheiten mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">c=1<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>s<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>4<\/mn><mo>−<\/mo><mn>9<\/mn><mo>=<\/mo><mi>−<\/mi><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s^2=4-9=-5<\/annotation><\/semantics><\/math>.\nSie liegen raumartig getrennt. Im Diagramm befindet sich ein Punkt\naußerhalb des Lichtkegels; dort kann das Feldkommutator-Signal kein\nkausales Signal auslösen.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_152_DE.svg\"\nalt=\"Lichtkegeldiagramm in ct-x-Koordinaten mit einem markierten raumartig getrennten Ereignis außerhalb des Kegels.\" />\n<figcaption aria-hidden=\"true\">Lichtkegeldiagramm in ct-x-Koordinaten\nmit einem markierten raumartig getrennten Ereignis außerhalb des\nKegels.<\/figcaption>\n<\/figure>\n<p><em>Raumartige Trennung bedeutet: Zwischen den markierten Ereignissen\nist kein Licht- oder langsameres Signal möglich.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>t<\/mi><mo>=<\/mo><mn>4<\/mn><mo>,<\/mo><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Δ<\/mi><mi>x<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta t=4,\\,\\Delta x=3<\/annotation><\/semantics><\/math>\nzeitartig oder raumartig?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wofür steht das Symbol\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>D<\/mi><mi>F<\/mi><\/msub><annotation encoding=\"application/x-tex\">D_F<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum bedeutet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D<\/mi><mi>F<\/mi><\/msub><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">D_F\\neq0<\/annotation><\/semantics><\/math>\naußerhalb des Lichtkegels nicht automatisch Überlichtkommunikation?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>s<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>16<\/mn><mo>−<\/mo><mn>9<\/mn><mo>=<\/mo><mn>7<\/mn><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s^2=16-9=7&gt;0<\/annotation><\/semantics><\/math>:\nzeitartig.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Für die Zeitordnung der Feldoperatoren.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Weil Mikrokausalität und Signalübertragung durch den Kommutator,\nnicht allein durch den zeitgeordneten Korrelator, eingeschränkt\nwerden.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die angegebene Kommutatorrelation setzt lokale bosonische Felder\nvoraus; bei Fermionen sind entsprechende Antikommutatoren relevant. Die\nvereinfachte Skizze zeigt 1+1 Dimensionen, keine vollständige\n3+1-dimensionale Raumzeit.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Zeitgeordnete Korrelatoren dienen als Bausteine für Störungsreihen\nund Streuamplituden. <a href=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://davidtong.org/teaching/quantum-field-theory/\">Tong – Quantum Field Theory<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel 2: Kausalität und Propagatoren; Fachlicher Bezug zur Lektion: M30-L3 – Propagatoren und Mikrokausalität · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M30-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M30-L4 – Wechselwirkungen, Wick-Theorem und Streuamplituden<\/h1>\n<p><strong>Kursbereich:<\/strong> M30 – Master: Quantenfeldtheorie und Standardmodell<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M30-L3: zeitgeordnete Korrelatoren\n· <a href=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige Lektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Den Zusammenhang zwischen\nWechselwirkungsterm, Wick-Kontraktionen und einer elementaren\nStreuamplitude erklären.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Messbare Streuprozesse erfordern Wechselwirkungen. In der Feldtheorie\nentwickelt man zeitgeordnete Produkte häufig in einer Störungsreihe nach\nder Kopplungsstärke. Das Wick-Theorem zerlegt freie zeitgeordnete\nOperatorprodukte in Normalordnungen und Kontraktionen; Feynman-Diagramme\norganisieren die resultierenden Terme.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Als Modell wählen wir einen reellen Skalar mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"script\">ℒ<\/mi><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>−<\/mi><mi>λ<\/mi><msup><mi>ϕ<\/mi><mn>4<\/mn><\/msup><mi>/<\/mi><mn>4<\/mn><mi>!<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal L_{\\mathrm{int}}=-\\lambda\\phi^4/4!<\/annotation><\/semantics><\/math>.\nDas Vier-Felder-Produkt erzeugt einen lokalen Vertex mit vier Beinen.\nDer Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4<\/mn><mi>!<\/mi><\/mrow><annotation encoding=\"application/x-tex\">4!<\/annotation><\/semantics><\/math>\ngleicht die Zahl der Permutationen bei den entsprechenden Kontraktionen\naus. Unter den üblichen Konventionen lautet der Baumdiagramm-Vertex\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mi>i<\/mi><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">-i\\lambda<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i<\/mi><mi mathvariant=\"script\">ℳ<\/mi><mo>=<\/mo><mi>−<\/mi><mi>i<\/mi><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">i\\mathcal M=-i\\lambda<\/annotation><\/semantics><\/math>\nfür den Kontaktbeitrag der\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo>→<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2\\to2<\/annotation><\/semantics><\/math>-Streuung.\nFür vollständige Raten sind zusätzlich äußere Zustandsnormierungen,\nPhasenraum, eventuelle Symmetriefaktoren und gegebenenfalls weitere\nDiagramme nötig.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"script\">ℒ<\/mi><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>−<\/mi><mfrac><mi>λ<\/mi><mrow><mn>4<\/mn><mi>!<\/mi><\/mrow><\/mfrac><msup><mi>ϕ<\/mi><mn>4<\/mn><\/msup><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>i<\/mi><msub><mi mathvariant=\"script\">ℳ<\/mi><mrow><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">e<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>−<\/mi><mi>i<\/mi><mi>λ<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal L_{\\mathrm{int}}=-\\frac{\\lambda}{4!}\\phi^4,\\qquad i\\mathcal M_{\\mathrm{tree}}=-i\\lambda.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für eine illustrative dimensionslose Kopplung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>20<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=0{,}20<\/annotation><\/semantics><\/math>\nergibt der Kontaktterm\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi mathvariant=\"script\">ℳ<\/mi><mrow><mi mathvariant=\"normal\">t<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">e<\/mi><\/mrow><\/msub><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>040<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|\\mathcal M_{\\mathrm{tree}}|^2=0{,}040<\/annotation><\/semantics><\/math>.\nDiese Zahl ist <strong>kein<\/strong> Wirkungsquerschnitt. Die Zeichnung\nzeigt vier Linien, die sich an einem gemeinsamen Kontaktvertex treffen;\nsie ist eine kombinatorische Darstellung, keine Teilchenbahn.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_256_DE.svg\"\nalt=\"Vier ein- und ausgehende Feldlinien treffen an einem Punkt mit Beschriftung λ zusammen.\" />\n<figcaption aria-hidden=\"true\">Vier ein- und ausgehende Feldlinien\ntreffen an einem Punkt mit Beschriftung λ zusammen.<\/figcaption>\n<\/figure>\n<p><em>Der lokale\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>ϕ<\/mi><mn>4<\/mn><\/msup><annotation encoding=\"application/x-tex\">\\phi^4<\/annotation><\/semantics><\/math>-Term\nerzeugt einen Vierpunktvertex.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie viele äußere Linien hat ein\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>ϕ<\/mi><mn>4<\/mn><\/msup><annotation encoding=\"application/x-tex\">\\phi^4<\/annotation><\/semantics><\/math>-Kontaktvertex?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie ändert sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"script\">ℳ<\/mi><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">|\\mathcal M|^2<\/annotation><\/semantics><\/math>\nbei Verdopplung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>λ<\/mi><annotation encoding=\"application/x-tex\">\\lambda<\/annotation><\/semantics><\/math>\nauf Baumebene?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Welche weitere Größe benötigt man für einen Wirkungsquerschnitt\nneben der Amplitude?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Vier.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Es vervierfacht sich.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Mindestens die Integration über den kinematisch erlaubten Phasenraum\nmit passender Normierung und Flussgröße.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die einfache Baumamplitude gilt für die angegebene Wechselwirkung und\nführende Störungsordnung. Reale Streuquerschnitte sind energie- und\nmodellabhängig. Diagramme sind Rechenbeiträge zu Amplituden, keine\nBeobachtungsfotos mikroskopischer Prozesse.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Bei höherer Ordnung treten Schleifenintegrale auf; ihre\nSkalenabhängigkeit führt zu Renormierung und effektiven Theorien. <a\nhref=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://davidtong.org/teaching/quantum-field-theory/\">Tong – Quantum Field Theory<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel 3: Wick-Theorem, Feynman-Regeln und Streuung; Fachlicher Bezug zur Lektion: M30-L4 – Wechselwirkungen, Wick-Theorem und Streuamplituden · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M30-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M30-L5 – Pfadintegrale, Renormierung und effektive Feldtheorien<\/h1>\n<p><strong>Kursbereich:<\/strong> M30 – Master: Quantenfeldtheorie und Standardmodell<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M30-L4: Störungsdiagramme und\nAmplituden · <a href=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige\nLektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Das Pfadintegral als Gewichtung von\nFeldkonfigurationen verstehen und Energiesuppression höherdimensionaler\nOperatoren abschätzen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Wie kann eine Theorie bei niedriger Energie nützlich sein, obwohl\nihre mikroskopischen Details unbekannt bleiben? Pfadintegrale geben eine\nzweite Formulierung von Feldkorrelationen. Die effektive Feldtheorie\ntrennt niedrigenergetisch beobachtbare Effekte von der hohen Skala, bei\nder zusätzliche Freiheitsgrade relevant werden.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Formal lautet das erzeugende Funktional\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Z<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>J<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mo>∫<\/mo><mspace width=\"-0.167em\"><\/mspace><mi mathvariant=\"script\">𝒟<\/mi><mi>ϕ<\/mi><mspace width=\"0.167em\"><\/mspace><msup><mi>e<\/mi><mrow><mi>i<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>+<\/mo><mo>∫<\/mo><mi>J<\/mi><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">Z[J]=\\int\\!\\mathcal D\\phi\\,e^{i(S[\\phi]+\\int J\\phi)}<\/annotation><\/semantics><\/math>.\nDiese Schreibweise setzt eine geeignete Regularisierung und Definition\ndes Integrationsmaßes voraus. In einer effektiven Lagrange-Dichte ordnet\nman lokale Operatoren nach ihrer Massendimension. In vier\nRaumzeitdimensionen wird ein Operator\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi mathvariant=\"script\">𝒪<\/mi><mn>6<\/mn><\/msub><annotation encoding=\"application/x-tex\">\\mathcal O_6<\/annotation><\/semantics><\/math>\nder Dimension sechs mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>c<\/mi><mn>6<\/mn><\/msub><mi>/<\/mi><msup><mi mathvariant=\"normal\">Λ<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">c_6/\\Lambda^2<\/annotation><\/semantics><\/math>\ngewichtet. Für charakteristische Energie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>≪<\/mo><mi mathvariant=\"normal\">Λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E\\ll\\Lambda<\/annotation><\/semantics><\/math>\nist sein amplitudenartiger Beitrag gegenüber typischen dimensionsvier\nBeiträgen größenordnungsmäßig\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>E<\/mi><mi>/<\/mi><mi mathvariant=\"normal\">Λ<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">(E/\\Lambda)^2<\/annotation><\/semantics><\/math>,\nsofern dimensionslose Koeffizienten und Matrixelemente nicht\nungewöhnlich groß sind. Die Renormierungsgruppe verfolgt, wie Parameter\nmit der Auswertungsskala laufen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"script\">ℒ<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mo>=<\/mo><msub><mi mathvariant=\"script\">ℒ<\/mi><mrow><mo>≤<\/mo><mn>4<\/mn><\/mrow><\/msub><mo>+<\/mo><mfrac><msub><mi>c<\/mi><mn>6<\/mn><\/msub><msup><mi mathvariant=\"normal\">Λ<\/mi><mn>2<\/mn><\/msup><\/mfrac><msub><mi mathvariant=\"script\">𝒪<\/mi><mn>6<\/mn><\/msub><mo>+<\/mo><mi>⋯<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal L_{\\mathrm{eff}}=\\mathcal L_{\\leq4}+\\frac{c_6}{\\Lambda^2}\\mathcal O_6+\\cdots.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mi>/<\/mi><mi mathvariant=\"normal\">Λ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E/\\Lambda=0{,}10<\/annotation><\/semantics><\/math>\nbeträgt der erwartete dimensionslose Unterdrückungsfaktor eines solchen\nAmplitudenbeitrags etwa\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>01<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}01<\/annotation><\/semantics><\/math>.\nDas Diagramm zeigt zwei Skalen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>E<\/mi><annotation encoding=\"application/x-tex\">E<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Λ<\/mi><annotation encoding=\"application/x-tex\">\\Lambda<\/annotation><\/semantics><\/math>;\nes behauptet nicht, dass jede beobachtbare Rate um exakt ein Hundertstel\nsinkt. Bei Interferenz mit führenden Beiträgen sind andere Skalierungen\nmöglich.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_077_DE.svg\"\nalt=\"Zwei Energieskalen mit einem großen Hochenergieblock und einem kleineren Niedrigenergieblock; dazwischen eine gedämpfte Korrektur.\" />\n<figcaption aria-hidden=\"true\">Zwei Energieskalen mit einem großen\nHochenergieblock und einem kleineren Niedrigenergieblock; dazwischen\neine gedämpfte Korrektur.<\/figcaption>\n<\/figure>\n<p><em>Operatoren höherer Massendimension liefern bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>≪<\/mo><mi mathvariant=\"normal\">Λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E\\ll\\Lambda<\/annotation><\/semantics><\/math>\nkontrolliert kleine Korrekturen, sofern die EFT-Annahmen\ngelten.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>E<\/mi><mi>/<\/mi><mi mathvariant=\"normal\">Λ<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">(E/\\Lambda)^2<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E=2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Λ<\/mi><mo>=<\/mo><mn>20<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Lambda=20<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum wird ein dimensionssechs-Operator durch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi mathvariant=\"normal\">Λ<\/mi><mrow><mi>−<\/mi><mn>2<\/mn><\/mrow><\/msup><annotation encoding=\"application/x-tex\">\\Lambda^{-2}<\/annotation><\/semantics><\/math>\nbegleitet?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Ist ein durch Schleifen korrigierter Kopplungsparameter\ntypischerweise skalenunabhängig?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>01<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}01<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Damit die Lagrange-Dichte in vier Dimensionen insgesamt die\nMassendimension vier hat.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Nein; sein renormierter Wert hängt im Allgemeinen von der\nRenormierungsskala ab.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Pfadintegrale sind in diesem Kontext formale Ausdrücke; mathematische\nExistenzfragen werden nicht durch die Kurzformel gelöst. Eine effektive\nTheorie gilt nur unterhalb ihrer angenommenen Grenzskala und bei\nausreichend kontrollierter Entwicklung.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die Methode wird auf relativistische Spinorfelder und\nelektromagnetische Eichkopplungen übertragen. <a\nhref=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.damtp.cam.ac.uk/user/dbs26/AQFT.html\">Skinner – Quantum Field Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Inhaltsübersicht: Pfadintegrale, Wilson-EFT und Renormierungsgruppe; Fachlicher Bezug zur Lektion: M30-L5 – Pfadintegrale, Renormierung und effektive Feldtheorien · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://davidtong.org/teaching/quantum-field-theory/\">Tong – Quantum Field Theory<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel 3: Wechselwirkungen als Ausgangspunkt; Fachlicher Bezug zur Lektion: M30-L5 – Pfadintegrale, Renormierung und effektive Feldtheorien · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M30-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M30-L6 – Dirac-Felder und Quantenelektrodynamik<\/h1>\n<p><strong>Kursbereich:<\/strong> M30 – Master: Quantenfeldtheorie und Standardmodell<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M30-L5: Feldwechselwirkungen; M25:\nSpin · <a href=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige\nLektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Den Unterschied zwischen Spinorfeld und\nSkalarfeld benennen und die Struktur des QED-Vertices erkennen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Elektronen haben Spin 1/2 und erfüllen das Pauli-Prinzip. Sie lassen\nsich daher nicht durch dasselbe bosonische Skalarfeld wie M30-L1\nbeschreiben. Die Dirac-Gleichung verwendet Spinoren und Matrizen; die\nQuantenelektrodynamik (QED) koppelt diese geladenen Felder an das\nelektromagnetische Eichfeld.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Die Dirac-Matrizen erfüllen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msup><mi>γ<\/mi><mi>μ<\/mi><\/msup><mo>,<\/mo><msup><mi>γ<\/mi><mi>ν<\/mi><\/msup><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><mn>2<\/mn><msup><mi>η<\/mi><mrow><mi>μ<\/mi><mi>ν<\/mi><\/mrow><\/msup><mn mathvariant=\"bold\">𝟏<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\{\\gamma^\\mu,\\gamma^\\nu\\}=2\\eta^{\\mu\\nu}\\mathbf1<\/annotation><\/semantics><\/math>\nfür die Signatur\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>+<\/mi><mo>−<\/mo><mi>−<\/mi><mi>−<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(+---)<\/annotation><\/semantics><\/math>.\nEin freies Spinorfeld erfüllt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>i<\/mi><msup><mi>γ<\/mi><mi>μ<\/mi><\/msup><msub><mi>∂<\/mi><mi>μ<\/mi><\/msub><mo>−<\/mo><mi>m<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>ψ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(i\\gamma^\\mu\\partial_\\mu-m)\\psi=0<\/annotation><\/semantics><\/math>.\nElektromagnetische Kopplung erfolgt durch den kovarianten\nAbleitungsoperator\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D<\/mi><mi>μ<\/mi><\/msub><mo>=<\/mo><msub><mi>∂<\/mi><mi>μ<\/mi><\/msub><mo>+<\/mo><mi>i<\/mi><mi>e<\/mi><msub><mi>A<\/mi><mi>μ<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">D_\\mu=\\partial_\\mu+ieA_\\mu<\/annotation><\/semantics><\/math>\nfür die hier gewählte Konvention des Elektronenfelds; die beobachtbaren\nAussagen hängen nicht von der willkürlichen gemeinsamen\nVorzeichenkonvention ab. Der Wechselwirkungsterm ergibt einen Vertex mit\nzwei Fermionlinien und einer Photonlinie. Die Modenanregungen des\nFermionfeldes gehorchen Antikommutationsrelationen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>i<\/mi><msup><mi>γ<\/mi><mi>μ<\/mi><\/msup><msub><mi>D<\/mi><mi>μ<\/mi><\/msub><mo>−<\/mo><mi>m<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>ψ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>D<\/mi><mi>μ<\/mi><\/msub><mo>=<\/mo><msub><mi>∂<\/mi><mi>μ<\/mi><\/msub><mo>+<\/mo><mi>i<\/mi><mi>e<\/mi><msub><mi>A<\/mi><mi>μ<\/mi><\/msub><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">(i\\gamma^\\mu D_\\mu-m)\\psi=0,\\qquad D_\\mu=\\partial_\\mu+ieA_\\mu.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Die dimensionslose Feinstrukturkonstante beträgt bei niedriger\nEnergieskala näherungsweise\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>α<\/mi><mo>=<\/mo><msup><mi>e<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≈<\/mo><mn>1<\/mn><mi>/<\/mi><mn>137<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\alpha=e^2/(4\\pi)\\approx1/137<\/annotation><\/semantics><\/math>\nin natürlichen Heaviside-Lorentz-Einheiten. Ein Beitrag mit zwei\nelektromagnetischen Kopplungsfaktoren in der Amplitude ist\ngrößenordnungsmäßig proportional zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">e^2<\/annotation><\/semantics><\/math>,\nwobei die vollständige Rate noch Kinematik und Diagrammstruktur\nbenötigt. Die Grafik zeigt den elementaren Fermion-Photon-Vertex.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_229_DE.svg\"\nalt=\"QED-Vertex: ein durchgehender Fermionpfeil trifft auf eine gewellte Photonlinie.\" />\n<figcaption aria-hidden=\"true\">QED-Vertex: ein durchgehender\nFermionpfeil trifft auf eine gewellte Photonlinie.<\/figcaption>\n<\/figure>\n<p><em>Ein elementarer QED-Vertex koppelt zwei Fermionbeine an ein\nPhotonbein.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Statistik haben Dirac-Fermionen?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie viele Fermionlinien und Photonlinien treffen an einem\nelementaren QED-Vertex zusammen?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Was bedeutet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msup><mi>γ<\/mi><mn>0<\/mn><\/msup><mo>,<\/mo><msup><mi>γ<\/mi><mn>0<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><mn>2<\/mn><mn mathvariant=\"bold\">𝟏<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\{\\gamma^0,\\gamma^0\\}=2\\mathbf1<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Fermi-Dirac-Statistik mit Antikommutationsrelationen.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Zwei Fermionlinien und eine Photonlinie.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>γ<\/mi><mn>0<\/mn><\/msup><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mn mathvariant=\"bold\">𝟏<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(\\gamma^0)^2=\\mathbf1<\/annotation><\/semantics><\/math>\nbei der gewählten Signatur.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Der gezeichnete Vertex ist nur die einfachste QED-Wechselwirkung und\nkeine vollständige experimentelle Vorhersage. Bei hohen Energien läuft\ndie Kopplung; zudem braucht eine präzise Rechnung Regularisierung,\nRenormierung und passende beobachtbare Größen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>M30-L7 erweitert die abelsche Eichidee auf die nichtabelsche starke\nWechselwirkung. <a href=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://davidtong.org/teaching/quantum-field-theory/\">Tong – Quantum Field Theory<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel 4–6: Dirac-Gleichung, Fermionquantisierung, QED; Fachlicher Bezug zur Lektion: M30-L6 – Dirac-Felder und Quantenelektrodynamik · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://davidtong.org/teaching/standard-model/\">Tong – The Standard Model<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel 1: Eichinvarianz als Strukturprinzip; Fachlicher Bezug zur Lektion: M30-L6 – Dirac-Felder und Quantenelektrodynamik · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M30-L7":"<article class=\"lesson-standard\"><h1 id=\"L7\">M30-L7 – Nichtabelsche Eichtheorien und Quantenchromodynamik<\/h1>\n<p><strong>Kursbereich:<\/strong> M30 – Master: Quantenfeldtheorie und Standardmodell<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M30-L6: QED; M30-L5:\nRenormierungsgruppe · <a href=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige\nLektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Die Rolle der Farbladung erklären und das\nein-Schleifen-Laufen der starken Kopplung qualitativ und numerisch\ndeuten.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Quarks tragen eine dreifache Farbfreiheit, und acht Gluonen\nvermitteln die starke Wechselwirkung. Die Eichgruppe ist SU(3). Im\nUnterschied zur elektromagnetischen U(1)-Theorie tragen Gluonen selbst\nFarbladung und wechselwirken untereinander. Das verändert die\nEnergieskalenabhängigkeit der Kopplung grundlegend.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Im perturbativen Bereich und bei festem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>n<\/mi><mi>f<\/mi><\/msub><annotation encoding=\"application/x-tex\">n_f<\/annotation><\/semantics><\/math>\naktiven Quarkflavours lautet der führende Lauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>α<\/mi><mi>s<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>Q<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>4<\/mn><mi>π<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>β<\/mi><mn>0<\/mn><\/msub><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>Q<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><msup><mi mathvariant=\"normal\">Λ<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\alpha_s(Q^2)=4\\pi/[\\beta_0\\ln(Q^2/\\Lambda^2)]<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>β<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>11<\/mn><mo>−<\/mo><mn>2<\/mn><msub><mi>n<\/mi><mi>f<\/mi><\/msub><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\beta_0=11-2n_f/3<\/annotation><\/semantics><\/math>\nfür SU(3). Der positive Koeffizient\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>β<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">\\beta_0<\/annotation><\/semantics><\/math>\nführt zur asymptotischen Freiheit: bei größerem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Q<\/mi><annotation encoding=\"application/x-tex\">Q<\/annotation><\/semantics><\/math>\nwird die Kopplung kleiner. Die Formel ist eine Ein-Schleifen-Näherung;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Λ<\/mi><annotation encoding=\"application/x-tex\">\\Lambda<\/annotation><\/semantics><\/math>\nhängt von Konvention und Renormierungsschema ab. Für kleine\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Q<\/mi><annotation encoding=\"application/x-tex\">Q<\/annotation><\/semantics><\/math>\nist der perturbative Ansatz nicht verlässlich. Die Begriffe Confinement\nund Hadronisierung benötigen darüber hinaus nichtperturbative\nPhysik.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>α<\/mi><mi>s<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>Q<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mfrac><mrow><mn>4<\/mn><mi>π<\/mi><\/mrow><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>11<\/mn><mo>−<\/mo><mstyle displaystyle=\"false\"><mfrac><mn>2<\/mn><mn>3<\/mn><\/mfrac><\/mstyle><msub><mi>n<\/mi><mi>f<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>Q<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><msup><mi mathvariant=\"normal\">Λ<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/mfrac><mspace width=\"2.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>Q<\/mi><mo>≫<\/mo><mi mathvariant=\"normal\">Λ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\alpha_s(Q^2)=\\frac{4\\pi}{(11-\\tfrac23 n_f)\\ln(Q^2/\\Lambda^2)}\\qquad(Q\\gg\\Lambda).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Als <strong>illustrative<\/strong> Rechnung mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mi>f<\/mi><\/msub><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_f=3<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mi>/<\/mi><mi mathvariant=\"normal\">Λ<\/mi><mo>=<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q/\\Lambda=10<\/annotation><\/semantics><\/math>\nerhält man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>β<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>9<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\beta_0=9<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>α<\/mi><mi>s<\/mi><\/msub><mo>≈<\/mo><mn>4<\/mn><mi>π<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>9<\/mn><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>100<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>303<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\alpha_s\\approx4\\pi/[9\\ln(100)]\\approx0{,}303<\/annotation><\/semantics><\/math>.\nBei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mi>/<\/mi><mi mathvariant=\"normal\">Λ<\/mi><mo>=<\/mo><mn>20<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q/\\Lambda=20<\/annotation><\/semantics><\/math>\nergibt dieselbe Näherung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>α<\/mi><mi>s<\/mi><\/msub><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>233<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\alpha_s\\approx0{,}233<\/annotation><\/semantics><\/math>.\nDie Kurve zeigt das Abfallen, nicht präzise experimentelle\nKopplungswerte für ein festes Teilchenexperiment.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_228_DE.svg\"\nalt=\"Ein-Schleifen-Kurve einer sinkenden starken Kopplung gegen Q geteilt durch Lambda im perturbativen Bereich.\" />\n<figcaption aria-hidden=\"true\">Ein-Schleifen-Kurve einer sinkenden\nstarken Kopplung gegen Q geteilt durch Lambda im perturbativen\nBereich.<\/figcaption>\n<\/figure>\n<p><em>Mit größerer Energieskala wird die starke Kopplung im\nperturbativen Regime schwächer.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>β<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">\\beta_0<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mi>f<\/mi><\/msub><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_f=3<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie ändert sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>α<\/mi><mi>s<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\alpha_s<\/annotation><\/semantics><\/math>\nqualitativ mit wachsendem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Q<\/mi><annotation encoding=\"application/x-tex\">Q<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Weshalb darf die Ein-Schleifen-Kurve nicht bis\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><mi mathvariant=\"normal\">Λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Q=\\Lambda<\/annotation><\/semantics><\/math>\nals Messkurve fortgesetzt werden?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Neun.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Sie sinkt im perturbativen Bereich.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Weil der Logarithmus im Nenner gegen null geht und die\nStörungsentwicklung ihre Gültigkeit verliert.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Der numerische Vergleich fixiert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mi>f<\/mi><\/msub><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_f=3<\/annotation><\/semantics><\/math>\nauch über die Beispielskalen; an physikalischen Quarkschwellen sind\nAnpassungen nötig. Konfinierung folgt nicht direkt aus dem einfachen\nein-Schleifen-Ausdruck und bleibt eine nichtperturbative\nEigenschaft.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Das Standardmodell enthält zusätzlich die elektroschwache\nWechselwirkung und ihren Higgs-Mechanismus. <a\nhref=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L8&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://davidtong.org/teaching/standard-model/\">Tong – The Standard Model<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel 3: QCD und asymptotische Freiheit; Fachlicher Bezug zur Lektion: M30-L7 – Nichtabelsche Eichtheorien und Quantenchromodynamik · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.damtp.cam.ac.uk/user/dbs26/AQFT.html\">Skinner – Quantum Field Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Abschnitte zur nichtabelschen Eichkopplung und Betafunktion; Fachlicher Bezug zur Lektion: M30-L7 – Nichtabelsche Eichtheorien und Quantenchromodynamik · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M30-L8":"<article class=\"lesson-standard\"><h1 id=\"L8\">M30-L8 – Elektroschwache Symmetriebrechung und Higgs-Mechanismus<\/h1>\n<p><strong>Kursbereich:<\/strong> M30 – Master: Quantenfeldtheorie und Standardmodell<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M30-L7: Eichsymmetrien; M30-L5:\neffektive Potentiale · <a href=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige\nLektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Das Minimum eines symmetrischen Potentials\nvon einer gewählten Vakuumkonfiguration unterscheiden und die W-Masse\nabschätzen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Die elektromagnetische und die schwache Wechselwirkung gehören\ngemeinsam zum elektroschwachen Sektor des Standardmodells. Seine lokale\nEichstruktur bleibt als Beschreibung bestehen, obwohl das Higgs-Feld\neinen nichtverschwindenden Vakuumerwartungswert besitzt. Die\nphysikalischen W- und Z-Bosonen werden dadurch massiv, das Photon bleibt\nmasselos.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Ein vereinfachter reeller Schnitt durch ein symmetrisches Potential\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>φ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>λ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>φ<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><msup><mi>v<\/mi><mn>2<\/mn><\/msup><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">V(\\varphi)=\\lambda(\\varphi^2-v^2)^2/4<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda&gt;0<\/annotation><\/semantics><\/math>.\nDas Potential ist unter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>φ<\/mi><mo>↦<\/mo><mi>−<\/mi><mi>φ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\varphi\\mapsto-\\varphi<\/annotation><\/semantics><\/math>\ninvariant, besitzt aber Minima bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>φ<\/mi><mo>=<\/mo><mi>±<\/mi><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\varphi=\\pm v<\/annotation><\/semantics><\/math>.\nDies illustriert die Auswahl einer Vakuumkonfiguration, ist aber\n<strong>nicht<\/strong> die vollständige eichinvariante\nHiggs-Dublett-Theorie. Im Standardmodell erzeugt der\nVakuumerwartungswert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo>≈<\/mo><mn>246<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">v\\approx246\\,\\mathrm{GeV}<\/annotation><\/semantics><\/math>\naus dem kinetischen Term des Higgs-Dubletts unter anderem den Massenterm\ndes geladenen W-Bosons. Die lokale Eichfreiheit beschreibt eine\nRedundanz der Feldvariablen; sie ist keine gewöhnliche globale\nphysikalische Symmetrie, die im wörtlichen Sinn gebrochen werden\nmüsste.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m<\/mi><mi>W<\/mi><\/msub><mo>=<\/mo><mfrac><mrow><mi>g<\/mi><mi>v<\/mi><\/mrow><mn>2<\/mn><\/mfrac><mspace width=\"2.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ℏ<\/mi><mo>=<\/mo><mi>c<\/mi><mo>=<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">m_W=\\frac{gv}{2}\\qquad(\\hbar=c=1).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g<\/mi><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>65<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g\\approx0{,}65<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo>≈<\/mo><mn>246<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">v\\approx246\\,\\mathrm{GeV}<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>m<\/mi><mi>W<\/mi><\/msub><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>65<\/mn><mo>×<\/mo><mn>246<\/mn><mi>/<\/mi><mn>2<\/mn><mo>≈<\/mo><mn>79<\/mn><mo>,<\/mo><mn>95<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">m_W\\approx0{,}65\\times246/2\\approx79{,}95\\,\\mathrm{GeV}<\/annotation><\/semantics><\/math>.\nDie Skizze eines Doppelmuldenpotentials zeigt einen <strong>reellen\nModellquerschnitt<\/strong> mit Minima bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>±<\/mi><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\pm v<\/annotation><\/semantics><\/math>,\nnicht die Topologie des vollständigen elektroschwachen\nHiggs-Feldraums.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_131_DE.svg\"\nalt=\"Symmetrisches Doppelmuldenpotential als vereinfachter reeller Schnitt mit zwei Minima bei minus v und plus v.\" />\n<figcaption aria-hidden=\"true\">Symmetrisches Doppelmuldenpotential als\nvereinfachter reeller Schnitt mit zwei Minima bei minus v und plus\nv.<\/figcaption>\n<\/figure>\n<p><em>Eine symmetrische Dynamik kann mehrere gleichwertige mögliche\nVakuumkonfigurationen zulassen.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wo liegen die Minima von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>φ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>λ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>φ<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><msup><mi>v<\/mi><mn>2<\/mn><\/msup><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">V(\\varphi)=\\lambda(\\varphi^2-v^2)^2/4<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g<\/mi><mi>v<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">gv/2<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>g<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>65<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g=0{,}65<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo>=<\/mo><mn>246<\/mn><\/mrow><annotation encoding=\"application/x-tex\">v=246<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Ist die gezeichnete Doppelmulde das vollständige\nHiggs-Dublett-Potential?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>φ<\/mi><mo>=<\/mo><mi>−<\/mi><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\varphi=-v<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>φ<\/mi><mo>=<\/mo><mi>+<\/mi><mi>v<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\varphi=+v<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Etwa\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>79<\/mn><mo>,<\/mo><mn>95<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">79{,}95\\,\\mathrm{GeV}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Nein, nur ein vereinfachter reeller Schnitt mit analoger\nVakuumauswahl.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Der Wert für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>g<\/mi><annotation encoding=\"application/x-tex\">g<\/annotation><\/semantics><\/math>\nist eine grobe Skalenannahme; präzise Vorhersagen berücksichtigen\nradiative Korrekturen und eine festgelegte Renormierungskonvention. Die\neinfache Doppelmulde ist nur eine Analogie, keine Grafik der gesamten\nEichorbitstruktur.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>M30-L9 behandelt die zusätzliche Struktur von Fermionmassen,\nFlavour-Mischung und Neutrinooszillation. <a\nhref=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L9&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://davidtong.org/teaching/standard-model/\">Tong – The Standard Model<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel 2 und 5: Symmetriebrechung, Higgs-Mechanismus, Elektroschwach; Fachlicher Bezug zur Lektion: M30-L8 – Elektroschwache Symmetriebrechung und Higgs-Mechanismus · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.damtp.cam.ac.uk/user/dbs26/AQFT.html\">Skinner – Quantum Field Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Inhaltsübersicht: Eichtheorie und effektive Feldtheorie; Fachlicher Bezug zur Lektion: M30-L8 – Elektroschwache Symmetriebrechung und Higgs-Mechanismus · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M30-L9":"<article class=\"lesson-standard\"><h1 id=\"L9\">M30-L9 – Flavour-Mischung und Neutrinooszillationen<\/h1>\n<p><strong>Kursbereich:<\/strong> M30 – Master: Quantenfeldtheorie und Standardmodell<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M30-L8: elektroschwacher Sektor;\nM25: Superposition · <a href=\"index.html?course=university_physics&amp;module=M30&amp;lesson=L8&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorherige\nLektion<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Flavour- und Masseneigenzustände\nunterscheiden und die Zwei-Flavour-Oszillationswahrscheinlichkeit\nberechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>In schwachen Zerfällen werden Neutrinos in Flavourzuständen erzeugt,\ndie im Allgemeinen Superpositionen verschiedener Masseneigenzustände\nsind. Wegen der unterschiedlichen Phasenentwicklung kann sich der bei\neiner späteren Messung beobachtete Flavour ändern. Die analoge\nUnterscheidung zwischen Flavour- und Masseneigenbasis spielt auch bei\nQuarks und der CKM-Matrix eine Rolle; Neutrinos werden durch die\nPMNS-Mischung beschrieben.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Im vereinfachten Vakuummodell zweier Flavours ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>ν<\/mi><mi>a<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>ν<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>+<\/mo><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>ν<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|\\nu_a\\rangle=\\cos\\theta|\\nu_1\\rangle+\\sin\\theta|\\nu_2\\rangle<\/annotation><\/semantics><\/math>\nund der orthogonale Zustand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>ν<\/mi><mi>b<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mi>−<\/mi><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>ν<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>+<\/mo><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>ν<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|\\nu_b\\rangle=-\\sin\\theta|\\nu_1\\rangle+\\cos\\theta|\\nu_2\\rangle<\/annotation><\/semantics><\/math>.\nBei hochrelativistischen Teilchen ergibt die Phasendifferenz\nnäherungsweise\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mi>L<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>E<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\Delta m^2L/(2E)<\/annotation><\/semantics><\/math>\nund daraus eine Übergangswahrscheinlichkeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi>a<\/mi><mo>→<\/mo><mi>b<\/mi><\/mrow><\/msub><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mi>L<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mi>E<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">P_{a\\to b}=\\sin^2(2\\theta)\\sin^2(\\Delta m^2L/(4E))<\/annotation><\/semantics><\/math>.\nMit gebräuchlichen Einheiten für L und E beträgt der Umrechnungsfaktor\nim Sinusargument rund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>267<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1{,}267<\/annotation><\/semantics><\/math>.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi>a<\/mi><mo>→<\/mo><mi>b<\/mi><\/mrow><\/msub><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mspace width=\"-0.167em\"><\/mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mn>1.267<\/mn><mspace width=\"0.167em\"><\/mspace><mfrac><mrow><mi mathvariant=\"normal\">Δ<\/mi><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mspace width=\"0.167em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>L<\/mi><mspace width=\"0.167em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><mrow><mi>E<\/mi><mspace width=\"0.167em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_{a\\to b}=\\sin^2(2\\theta)\\sin^2\\!\\left(1.267\\,\\frac{\\Delta m^2\\,[\\mathrm{eV}^2]L\\,[\\mathrm{km}]}{E\\,[\\mathrm{GeV}]}\\right).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für das <strong>didaktische Zwei-Flavour-Beispiel<\/strong>\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>30<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=30^\\circ<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mn>5<\/mn><mo>×<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>3<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\Delta m^2=2{,}5\\times10^{-3}\\,\\mathrm{eV}^2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mo>=<\/mo><mn>295<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">L=295\\,\\mathrm{km}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>60<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">E=0{,}60\\,\\mathrm{GeV}<\/annotation><\/semantics><\/math>\nist das Argument\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>≈<\/mo><mn>1<\/mn><mo>,<\/mo><mn>557<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\approx1{,}557<\/annotation><\/semantics><\/math>.\nMit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>75<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sin^2(2\\theta)=0{,}75<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi>a<\/mi><mo>→<\/mo><mi>b<\/mi><\/mrow><\/msub><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>750<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_{a\\to b}\\approx0{,}750<\/annotation><\/semantics><\/math>.\nDas ist ausdrücklich <strong>keine<\/strong> vollständige Vorhersage für\nein reales\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ν<\/mi><mi>μ<\/mi><\/msub><mo>→<\/mo><msub><mi>ν<\/mi><mi>e<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\nu_\\mu\\to\\nu_e<\/annotation><\/semantics><\/math>-Experiment.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_188_DE.svg\"\nalt=\"Oszillierende Übergangswahrscheinlichkeit zwischen null und einer maximalen Höhe von 0,75 bei festem Mischungswinkel.\" />\n<figcaption aria-hidden=\"true\">Oszillierende Übergangswahrscheinlichkeit\nzwischen null und einer maximalen Höhe von 0,75 bei festem\nMischungswinkel.<\/figcaption>\n<\/figure>\n<p><em>Die vereinfachte Zwei-Flavour-Wahrscheinlichkeit oszilliert mit\ndem Verhältnis von Weglänge zu Energie.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist die maximal mögliche Übergangswahrscheinlichkeit bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>30<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=30^\\circ<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Was geschieht bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">L=0<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum reicht das Zwei-Flavour-Modell für Präzisionsmessungen nicht\naus?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mn>60<\/mn><mo>∘<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>75<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sin^2(60^\\circ)=0{,}75<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die Übergangswahrscheinlichkeit ist null.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Drei Massen-/Flavourzustände, CP-Phasen und Materieeffekte können\nrelevant sein.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Formel setzt kohärente Ausbreitung ultrarelativistischer\nNeutrinos im Vakuum und effektiv zwei Flavours voraus. Für reale\nPräzisionsanalysen werden die dreidimensionale PMNS-Matrix,\nMassenspektren, mögliche CP-Verletzung und Materieeffekte\nberücksichtigt. Das Modell lässt keine Aussage über unbekannte absolute\nNeutrinomassen zu.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Flavour-Mischung schließt die Einführung in wesentliche Feld- und\nStandardmodellbegriffe ab.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://davidtong.org/teaching/standard-model/\">Tong – The Standard Model<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kapitel 6–7: Flavour-Mischung und Neutrinomassen/-oszillationen; Fachlicher Bezug zur Lektion: M30-L9 – Flavour-Mischung und Neutrinooszillationen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.damtp.cam.ac.uk/user/dbs26/AQFT.html\">Skinner – Quantum Field Theory II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Vertiefung: effektive Theorie und Symmetrien (methodischer Hintergrund); Fachlicher Bezug zur Lektion: M30-L9 – Flavour-Mischung und Neutrinooszillationen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>"};
